import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const ENROLL_INSURANCE = ['국민연금', '건강보험', '고용보험', '산재보험'];
const ENROLL_REPORT = ['취득', '상실'];
const REPORT_TYPES = [
  'QUALIFICATION_ACQUISITION',
  'QUALIFICATION_LOSS',
  'TOTAL_REMUNERATION',
  'EMPLOYMENT_INDUSTRIAL',
  'SEPARATION_CONFIRMATION',
  'WORK_CONTENT_CONFIRMATION',
];
const INSURANCE_CODES = ['NATIONAL_PENSION', 'HEALTH', 'EMPLOYMENT', 'INDUSTRIAL_ACCIDENT'];
const INSURANCE_MAP: Record<string, string> = {
  '국민연금': 'NATIONAL_PENSION',
  '건강보험': 'HEALTH',
  '고용보험': 'EMPLOYMENT',
  '산재보험': 'INDUSTRIAL_ACCIDENT',
};
// 기간형 신고서: 대상 기간이 필요하다
const PERIOD_REPORTS = [
  'TOTAL_REMUNERATION',
  'EMPLOYMENT_INDUSTRIAL',
  'SEPARATION_CONFIRMATION',
  'WORK_CONTENT_CONFIRMATION',
];
const DATE_PATTERN = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const NUMBER_PATTERN = /^-?\d+(\.\d+)?$/;

function fail(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function text(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  return String(v);
}

function idOf(v: unknown, label: string, required: boolean): string | null {
  const s = text(v);
  if (s === null) {
    if (required) {
      throw fail(label + ' 값을 입력해 주세요.');
    }
    return null;
  }
  if (!/^\d+$/.test(s)) {
    throw fail(label + ' 값이 올바르지 않습니다.');
  }
  return s;
}

function dateOf(v: unknown, label: string): string | null {
  const s = text(v);
  if (s === null) {
    return null;
  }
  if (!DATE_PATTERN.test(s)) {
    throw fail(label + ' 형식이 올바르지 않습니다. (YYYY-MM-DD)');
  }
  return s;
}

function numberOf(v: unknown, label: string): string | null {
  const s = text(v);
  if (s === null) {
    return null;
  }
  if (!NUMBER_PATTERN.test(s)) {
    throw fail(label + ' 값은 숫자여야 합니다.');
  }
  return s;
}

function choice(v: unknown, label: string, list: string[], required: boolean): string | null {
  const s = text(v);
  if (s === null) {
    if (required) {
      throw fail(label + ' 값을 입력해 주세요.');
    }
    return null;
  }
  if (!list.includes(s)) {
    throw fail(label + ' 값이 올바르지 않습니다.');
  }
  return s;
}

function pageOf(q: Record<string, unknown>): { page: number; size: number } {
  const pageText = text(q['page']);
  const sizeText = text(q['size']);
  const page = pageText === null ? 0 : Number(pageText);
  let size = sizeText === null ? 20 : Number(sizeText);
  if (!Number.isInteger(page) || page < 0) {
    throw fail('page 값이 올바르지 않습니다.');
  }
  if (!Number.isInteger(size) || size < 1) {
    throw fail('size 값이 올바르지 않습니다.');
  }
  if (size > 200) {
    size = 200;
  }
  return { page, size };
}

@Controller('api/v1')
export class FnSfr02201Controller {
  @Post('/social-insurance-enrollments')
  @HttpCode(200)
  async createSocialInsuranceEnrollment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const employeeId = idOf(data['employeeId'], '임직원 ID', true);
    const insuranceType = choice(data['insuranceType'], '보험 종류', ENROLL_INSURANCE, true);
    const reportType = choice(data['reportType'], '신고 구분', ENROLL_REPORT, true);
    const acquisitionDate = dateOf(data['acquisitionDate'], '취득일');
    const lossDate = dateOf(data['lossDate'], '상실일');
    const lossReason = text(data['lossReason']);
    if (lossReason !== null && lossReason.length > 500) {
      throw fail('상실 사유는 500자 이내로 입력해 주세요.');
    }
    if (reportType === '취득') {
      if (acquisitionDate === null) {
        throw new ApiError(422, 'ENROLLMENT_DATE_REQUIRED', '취득 신고에는 취득일을 입력해 주세요.');
      }
      if (lossReason !== null) {
        throw new ApiError(422, 'ENROLLMENT_DATE_REQUIRED', '상실 사유는 자격상실 신고에서만 입력할 수 있습니다.');
      }
    } else {
      if (lossDate === null) {
        throw new ApiError(422, 'ENROLLMENT_DATE_REQUIRED', '상실 신고에는 상실일을 입력해 주세요.');
      }
      if (lossReason === null) {
        throw fail('상실 신고에는 상실 사유를 입력해 주세요.');
      }
    }
    return transaction(async (db) => {
      const records = await db.query(
        'SELECT personnel_record_id FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (records.length === 0) {
        throw new ApiError(404, 'PERSONNEL_RECORD_NOT_FOUND', '대상 임직원의 인사기록카드가 없습니다.');
      }
      const dup = await db.query(
        'SELECT social_insurance_enrollment_id FROM social_insurance_enrollment WHERE employee_id = CAST(:employeeId AS bigint) AND insurance_type = :insuranceType AND report_type = :reportType',
        { employeeId, insuranceType, reportType },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ENROLLMENT_DUPLICATED', '이미 등록된 대상자·신고 구분입니다.');
      }
      const rows = await db.query(
        `INSERT INTO social_insurance_enrollment
  (employee_id, insurance_type, report_type, acquisition_date, loss_date, loss_reason, created_at, updated_at)
VALUES
  (CAST(:employeeId AS bigint), :insuranceType, :reportType, CAST(:acquisitionDate AS date), CAST(:lossDate AS date), :lossReason, now(), now())
RETURNING social_insurance_enrollment_id AS "socialInsuranceEnrollmentId"`,
        {
          employeeId,
          insuranceType,
          reportType,
          acquisitionDate: reportType === '취득' || acquisitionDate !== null ? acquisitionDate : null,
          lossDate: reportType === '상실' ? lossDate : null,
          lossReason: reportType === '상실' ? lossReason : null,
        },
      );
      return rows[0];
    });
  }

  @Get('/social-insurance-enrollments')
  async listSocialInsuranceEnrollments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pageOf(q);
    const params = {
      employeeId: idOf(q['employeeId'], '임직원 ID', false),
      reportType: choice(q['reportType'], '신고 구분', ENROLL_REPORT, false),
      insuranceType: choice(q['insuranceType'], '보험 종류', ENROLL_INSURANCE, false),
    };
    return transaction(async (db) => {
      const where = `WHERE (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))
  AND (CAST(:reportType AS text) IS NULL OR report_type = CAST(:reportType AS text))
  AND (CAST(:insuranceType AS text) IS NULL OR insurance_type = CAST(:insuranceType AS text))`;
      const items = await db.query(
        `SELECT social_insurance_enrollment_id AS "socialInsuranceEnrollmentId",
  employee_id AS "employeeId",
  insurance_type AS "insuranceType",
  report_type AS "reportType",
  CAST(acquisition_date AS text) AS "acquisitionDate",
  CAST(loss_date AS text) AS "lossDate",
  loss_reason AS "lossReason"
FROM social_insurance_enrollment
${where}
ORDER BY social_insurance_enrollment_id DESC
LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...params, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM social_insurance_enrollment
${where}`,
        params,
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/social-insurance-reports')
  @HttpCode(200)
  async createSocialInsuranceReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const reportType = choice(data['reportType'], '신고서 종류', REPORT_TYPES, true) as string;
    let employeeId = idOf(data['employeeId'], '대상 임직원', false);
    const enrollmentId = idOf(data['socialInsuranceEnrollmentId'], '취득·상실 대상자', false);
    let insuranceType = choice(data['insuranceType'], '보험 종류', INSURANCE_CODES, false);
    const periodStart = dateOf(data['periodStart'], '대상 기간 시작일');
    const periodEnd = dateOf(data['periodEnd'], '대상 기간 종료일');
    let eventDate = dateOf(data['eventDate'], '취득일 또는 상실일');
    let lossReason = text(data['lossReason']);
    const totalAmount = numberOf(data['totalAmount'], '보수총액');
    if (lossReason !== null && lossReason.length > 200) {
      throw fail('상실 사유는 200자 이내로 입력해 주세요.');
    }
    if (lossReason !== null && reportType !== 'QUALIFICATION_LOSS') {
      throw fail('상실 사유는 자격상실 신고서에서만 입력할 수 있습니다.');
    }
    if (periodStart !== null && periodEnd !== null && periodEnd < periodStart) {
      throw fail('대상 기간 종료일은 시작일 이후여야 합니다.');
    }
    const isEvent = reportType === 'QUALIFICATION_ACQUISITION' || reportType === 'QUALIFICATION_LOSS';
    if (isEvent && enrollmentId === null) {
      throw new ApiError(404, 'ENROLLMENT_NOT_FOUND', '등록된 대상자가 없습니다.');
    }
    if (PERIOD_REPORTS.includes(reportType) && (periodStart === null || periodEnd === null)) {
      throw new ApiError(422, 'REPORT_DATA_NOT_FOUND', '신고서의 대상 기간을 입력해 주세요.');
    }
    return transaction(async (db) => {
      if (enrollmentId !== null) {
        const found = await db.query(
          `SELECT employee_id AS "employeeId",
  insurance_type AS "insuranceType",
  report_type AS "reportType",
  CAST(acquisition_date AS text) AS "acquisitionDate",
  CAST(loss_date AS text) AS "lossDate",
  loss_reason AS "lossReason"
FROM social_insurance_enrollment
WHERE social_insurance_enrollment_id = CAST(:enrollmentId AS bigint)`,
          { enrollmentId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'ENROLLMENT_NOT_FOUND', '등록된 대상자가 없습니다.');
        }
        const enrollment = found[0];
        const enrollmentEmployee = String(enrollment['employeeId']);
        if (employeeId !== null && employeeId !== enrollmentEmployee) {
          throw fail('대상자의 임직원과 신고서의 임직원이 다릅니다.');
        }
        employeeId = enrollmentEmployee;
        if (insuranceType === null) {
          insuranceType = INSURANCE_MAP[String(enrollment['insuranceType'])] ?? null;
        }
        if (reportType === 'QUALIFICATION_ACQUISITION') {
          if (enrollment['reportType'] !== '취득') {
            throw fail('취득 신고서는 취득 대상자로만 만들 수 있습니다.');
          }
          if (eventDate === null) {
            eventDate = text(enrollment['acquisitionDate']);
          }
        }
        if (reportType === 'QUALIFICATION_LOSS') {
          if (enrollment['reportType'] !== '상실') {
            throw fail('상실 신고서는 상실 대상자로만 만들 수 있습니다.');
          }
          if (eventDate === null) {
            eventDate = text(enrollment['lossDate']);
          }
          if (lossReason === null) {
            lossReason = text(enrollment['lossReason']);
          }
        }
      }
      if (isEvent && eventDate === null) {
        throw new ApiError(422, 'REPORT_DATA_NOT_FOUND', '취득일 또는 상실일 데이터가 없습니다.');
      }
      if (reportType === 'QUALIFICATION_LOSS' && lossReason === null) {
        throw fail('자격상실 신고서에는 상실 사유를 입력해 주세요.');
      }
      // 가정: 급여 테이블이 스펙에 없어 보수총액은 요청 값을 그대로 저장한다
      if (reportType === 'TOTAL_REMUNERATION' && totalAmount === null) {
        throw new ApiError(422, 'REPORT_DATA_NOT_FOUND', '대상 기간의 보수총액 데이터가 없습니다.');
      }
      if (employeeId !== null) {
        const records = await db.query(
          'SELECT personnel_record_id FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
          { employeeId },
        );
        if (records.length === 0) {
          throw new ApiError(422, 'REPORT_DATA_NOT_FOUND', '대상 임직원의 인사 데이터가 없습니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO social_insurance_report
  (employee_id, social_insurance_enrollment_id, report_type, insurance_type, period_start, period_end,
   event_date, loss_reason, total_amount, resident_number_enc, created_by_id, created_at, updated_at)
VALUES
  (CAST(:employeeId AS bigint), CAST(:enrollmentId AS bigint), :reportType, :insuranceType,
   CAST(:periodStart AS date), CAST(:periodEnd AS date), CAST(:eventDate AS date), :lossReason,
   CAST(:totalAmount AS numeric),
   (SELECT resident_number_enc FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)),
   CAST(:userId AS bigint), now(), now())
RETURNING social_insurance_report_id AS "socialInsuranceReportId", created_at AS "createdAt"`,
        {
          employeeId,
          enrollmentId,
          reportType,
          insuranceType,
          periodStart,
          periodEnd,
          eventDate,
          lossReason,
          totalAmount,
          userId: user.id,
        },
      );
      return rows[0];
    });
  }

  @Get('/social-insurance-reports')
  async listSocialInsuranceReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pageOf(q);
    const params = {
      employeeId: idOf(q['employeeId'], '대상 임직원', false),
      reportType: choice(q['reportType'], '신고서 종류', REPORT_TYPES, false),
      insuranceType: choice(q['insuranceType'], '보험 종류', INSURANCE_CODES, false),
    };
    return transaction(async (db) => {
      const where = `WHERE (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))
  AND (CAST(:reportType AS text) IS NULL OR report_type = CAST(:reportType AS text))
  AND (CAST(:insuranceType AS text) IS NULL OR insurance_type = CAST(:insuranceType AS text))`;
      const items = await db.query(
        `SELECT social_insurance_report_id AS "socialInsuranceReportId",
  employee_id AS "employeeId",
  report_type AS "reportType",
  insurance_type AS "insuranceType",
  CAST(event_date AS text) AS "eventDate",
  created_by_id AS "createdById",
  printed_at AS "printedAt",
  created_at AS "createdAt"
FROM social_insurance_report
${where}
ORDER BY social_insurance_report_id DESC
LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...params, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM social_insurance_report
${where}`,
        params,
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/social-insurance-reports/:socialInsuranceReportId/print')
  @HttpCode(200)
  async printSocialInsuranceReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const reportId = idOf(req.params['socialInsuranceReportId'], '신고서 ID', true);
    return transaction(async (db) => {
      // 가정: 출력 일시는 현재 시각으로 갱신한다
      const rows = await db.query(
        `UPDATE social_insurance_report
SET printed_at = now(), updated_at = now()
WHERE social_insurance_report_id = CAST(:reportId AS bigint)
RETURNING printed_at AS "printedAt"`,
        { reportId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'SOCIAL_INSURANCE_REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

