function labelOf(options: [string, string][], value: unknown): string {
  const found = options.find((o) => o[0] === value);
  return found ? found[1] : String(value ?? '');
}

function clean(source: Row): Row {
  const out: Row = {};
  Object.keys(source).forEach((key) => {
    const v = source[key];
    if (v !== '' && v !== undefined && v !== null) {
      out[key] = v;
    }
  });
  return out;
}

export default function FnSfr02201Page({ role, notify }: PageProps) {
  const [tab, setTab] = useState<'enrollment' | 'report'>('enrollment');
  const [page, setPage] = useState(0);
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [drawer, setDrawer] = useState<'' | 'enrollment' | 'report'>('');
  const [form, setForm] = useState<Row>({});

  const path = tab === 'enrollment' ? '/social-insurance-enrollments' : '/social-insurance-reports';
  const list = useData<Page>(
    () => call<Page>('GET', path, role, undefined, { ...applied, page, size: 20 }),
    [tab, applied, page],
  );

  function changeTab(next: 'enrollment' | 'report') {
    setTab(next);
    setDraft({});
    setApplied({});
    setPage(0);
  }

  function setF(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function openEnrollment() {
    setForm({});
    setDrawer('enrollment');
  }

  function openReport(row?: Row) {
    if (row) {
      setForm({
        socialInsuranceEnrollmentId: row.socialInsuranceEnrollmentId,
        employeeId: row.employeeId,
        reportType: row.reportType === '취득' ? 'QUALIFICATION_ACQUISITION' : 'QUALIFICATION_LOSS',
        insuranceType: INSURANCE_MAP[String(row.insuranceType)] ?? '',
      });
    } else {
      setForm({});
    }
    setDrawer('report');
  }

  async function submitEnrollment() {
    if (!form.employeeId) {
      throw new Error('임직원을 선택해 주세요.');
    }
    if (!form.insuranceType) {
      throw new Error('보험 종류를 선택해 주세요.');
    }
    if (!form.reportType) {
      throw new Error('신고 구분을 선택해 주세요.');
    }
    if (form.reportType === '취득' && !form.acquisitionDate) {
      throw new Error('취득 신고에는 취득일을 입력해 주세요.');
    }
    if (form.reportType === '상실' && !form.lossDate) {
      throw new Error('상실 신고에는 상실일을 입력해 주세요.');
    }
    if (form.reportType === '상실' && !form.lossReason) {
      throw new Error('상실 신고에는 상실 사유를 입력해 주세요.');
    }
    const body = clean(form);
    if (form.reportType === '취득') {
      delete body.lossDate;
      delete body.lossReason;
    }
    await call('POST', '/social-insurance-enrollments', role, body);
    setDrawer('');
    notify('대상자를 등록했습니다.');
    list.reload();
  }

  async function submitReport() {
    const type = String(form.reportType ?? '');
    if (!type) {
      throw new Error('신고서 종류를 선택해 주세요.');
    }
    const isEvent = type === 'QUALIFICATION_ACQUISITION' || type === 'QUALIFICATION_LOSS';
    if (isEvent && !form.socialInsuranceEnrollmentId) {
      throw new Error('취득·상실 대상자를 선택해 주세요.');
    }
    if (PERIOD_REPORTS.includes(type) && (!form.periodStart || !form.periodEnd)) {
      throw new Error('대상 기간을 입력해 주세요.');
    }
    if (type === 'TOTAL_REMUNERATION' && form.totalAmount === undefined) {
      throw new Error('보수총액을 입력해 주세요.');
    }
    const body = clean(form);
    if (type !== 'QUALIFICATION_LOSS') {
      delete body.lossReason;
    }
    await call('POST', '/social-insurance-reports', role, body);
    setDrawer('');
    notify('신고서를 생성했습니다.');
    list.reload();
  }

  async function printReport(row: Row) {
    try {
      await call('POST', '/social-insurance-reports/' + String(row.socialInsuranceReportId) + '/print', role, {});
      notify('신고서를 출력 처리했습니다.');
      list.reload();
    } catch (e) {
      notify(e instanceof Error ? e.message : '출력 처리에 실패했습니다.');
    }
  }

  const enrollmentColumns = [
    { key: 'employeeId', label: '임직원', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
    { key: 'insuranceType', label: '보험 종류' },
    { key: 'reportType', label: '신고 구분', render: (r: Row) => <Badge value={r.reportType} /> },
    {
      key: 'eventDate',
      label: '취득일·상실일',
      render: (r: Row) => <DateText value={r.reportType === '취득' ? r.acquisitionDate : r.lossDate} />,
    },
    {
      key: 'action',
      label: '처리',
      render: (r: Row) => (
        <button className="ghost" onClick={() => openReport(r)}>
          신고서 만들기
        </button>
      ),
    },
  ];

  const reportColumns = [
    { key: 'employeeId', label: '임직원', render: (r: Row) => (r.employeeId ? <RefName table="employee" role={role} value={r.employeeId} /> : <span>전체</span>) },
    { key: 'reportType', label: '신고서 종류', render: (r: Row) => <span>{labelOf(REPORT_TYPES, r.reportType)}</span> },
    { key: 'eventDate', label: '취득일·상실일', render: (r: Row) => <DateText value={r.eventDate} /> },
    { key: 'printedAt', label: '출력', render: (r: Row) => (r.printedAt ? <DateText value={r.printedAt} time /> : <Badge value="미출력" />) },
    {
      key: 'action',
      label: '처리',
      render: (r: Row) => (
        <button className="ghost" onClick={() => printReport(r)}>
          출력
        </button>
      ),
    },
  ];

  const reportType = String(form.reportType ?? '');

  return (
    <div>
      <h1>사회보험 취득·상실 관리</h1>
      <p>취득·상실 대상자를 등록하고, 대상자로 신고서를 만들어 출력합니다.</p>
      <div>
        <button className="ghost" onClick={() => changeTab('enrollment')}>
          대상자 목록
        </button>
        <button className="ghost" onClick={() => changeTab('report')}>
          신고서 이력
        </button>
      </div>

      <Filters
        onSearch={() => {
          setApplied(clean(draft));
          setPage(0);
        }}
        onReset={() => {
          setDraft({});
          setApplied({});
          setPage(0);
        }}
      >
        <Field label="임직원">
          <LookupSelect table="employee" role={role} value={draft.employeeId} onChange={(v) => setDraft({ ...draft, employeeId: v })} />
        </Field>
        <Field label={tab === 'enrollment' ? '신고 구분' : '신고서 종류'}>
          <Select
            value={draft.reportType}
            onChange={(v) => setDraft({ ...draft, reportType: v })}
            options={tab === 'enrollment' ? ENROLL_REPORT : REPORT_TYPES}
            placeholder="전체"
          />
        </Field>
        <Field label="보험 종류">
          <Select
            value={draft.insuranceType}
            onChange={(v) => setDraft({ ...draft, insuranceType: v })}
            options={tab === 'enrollment' ? ENROLL_INSURANCE : INSURANCE_CODES}
            placeholder="전체"
          />
        </Field>
      </Filters>

      <Band total={list.data?.total}>
        {tab === 'enrollment' ? (
          <button onClick={openEnrollment}>대상자 등록</button>
        ) : (
          <button className="ghost" onClick={() => openReport()}>
            신고서 생성
          </button>
        )}
      </Band>
      {list.error ? <ErrorText text={list.error} /> : null}
      <DataTable
        columns={tab === 'enrollment' ? enrollmentColumns : reportColumns}
        rows={list.data?.items ?? []}
        empty={tab === 'enrollment' ? '아직 등록한 대상자가 없습니다. 대상자 등록 버튼으로 시작해 주세요.' : '아직 생성한 신고서가 없습니다. 신고서 생성 버튼으로 시작해 주세요.'}
      />
      <Pager page={page} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPage} />

      {drawer === 'enrollment' ? (
        <Drawer title="취득·상실 대상자 등록" onClose={() => setDrawer('')}>
          <Form onSubmit={submitEnrollment} submit="등록">
            <Field label="임직원 ID" required>
              <LookupSelect table="employee" role={role} value={form.employeeId} onChange={(v) => setF('employeeId', v)} />
            </Field>
            <Field label="보험 종류" required>
              <Select value={form.insuranceType} onChange={(v) => setF('insuranceType', v)} options={ENROLL_INSURANCE} />
            </Field>
            <Field label="신고 구분" required>
              <Select value={form.reportType} onChange={(v) => setF('reportType', v)} options={ENROLL_REPORT} />
            </Field>
            {form.reportType === '취득' ? (
              <Field label="취득일" required>
                <DateInput value={form.acquisitionDate} onChange={(v) => setF('acquisitionDate', v)} />
              </Field>
            ) : null}
            {form.reportType === '상실' ? (
              <Field label="상실일" required>
                <DateInput value={form.lossDate} onChange={(v) => setF('lossDate', v)} />
              </Field>
            ) : null}
            {form.reportType === '상실' ? (
              <Field label="상실 사유" required wide>
                <TextInput value={form.lossReason} onChange={(v) => setF('lossReason', v)} multiline />
              </Field>
            ) : null}
          </Form>
        </Drawer>
      ) : null}

      {drawer === 'report' ? (
        <Drawer title="사회보험 신고서 생성" onClose={() => setDrawer('')}>
          <Form onSubmit={submitReport} submit="생성" note="대상자의 인사정보가 신고서에 자동으로 반영됩니다.">
            <Field label="신고서 종류" required>
              <Select value={form.reportType} onChange={(v) => setF('reportType', v)} options={REPORT_TYPES} />
            </Field>
            <Field label="취득·상실 대상자" required={reportType === 'QUALIFICATION_ACQUISITION' || reportType === 'QUALIFICATION_LOSS'}>
              <LookupSelect
                table="social_insurance_enrollment"
                role={role}
                value={form.socialInsuranceEnrollmentId}
                onChange={(v) => setF('socialInsuranceEnrollmentId', v)}
              />
            </Field>
            <Field label="대상 임직원">
              <LookupSelect table="employee" role={role} value={form.employeeId} onChange={(v) => setF('employeeId', v)} />
            </Field>
            <Field label="보험 종류">
              <Select value={form.insuranceType} onChange={(v) => setF('insuranceType', v)} options={INSURANCE_CODES} />
            </Field>
            <Field label="대상 기간 시작일" required={PERIOD_REPORTS.includes(reportType)}>
              <DateInput value={form.periodStart} onChange={(v) => setF('periodStart', v)} />
            </Field>
            <Field label="대상 기간 종료일" required={PERIOD_REPORTS.includes(reportType)}>
              <DateInput value={form.periodEnd} onChange={(v) => setF('periodEnd', v)} />
            </Field>
            {reportType === 'QUALIFICATION_ACQUISITION' || reportType === 'QUALIFICATION_LOSS' ? (
              <Field label="취득일 또는 상실일" hint="비워 두면 대상자의 날짜를 씁니다.">
                <DateInput value={form.eventDate} onChange={(v) => setF('eventDate', v)} />
              </Field>
            ) : null}
            {reportType === 'QUALIFICATION_LOSS' ? (
              <Field label="상실 사유" wide hint="비워 두면 대상자의 상실 사유를 씁니다.">
                <TextInput value={form.lossReason} onChange={(v) => setF('lossReason', v)} multiline />
              </Field>
            ) : null}
            {reportType === 'TOTAL_REMUNERATION' ? (
              <Field label="보수총액" required>
                <NumberInput value={form.totalAmount} onChange={(v) => setF('totalAmount', v)} />
              </Field>
            ) : null}
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
